# Independent dense reference files are generated by validation/check_spin_graph.py.
using Test, LinearAlgebra, ITensors, ITensorMPS, DelimitedFiles, Random
BLAS.set_num_threads(1)
include("../remote/engine/GenericSpinSites.jl")
using .GenericSpinSites
include("../remote/engine/SpinGraphHamiltonian.jl")
using .SpinGraphHamiltonian
root = ARGS[1]
@testset "Graph MPO and DMRG versus independent exact diagonalization" begin
    for (name, spins, edges) in [
        ("triangle", [0.5,0.5,0.5], [(1,2,1.0),(2,3,1.0),(1,3,1.0)]),
        ("branch", [0.5,1.0,0.5,0.5], [(1,2,0.8),(2,3,-0.3),(2,4,1.1)]),
        ("long_range", [0.5,0.5,0.5,0.5], [(1,2,1.0),(2,3,0.6),(3,4,0.9),(1,3,0.25),(1,4,-0.2)]),
        ("dimer", [0.5,0.5], [(1,2,1.0)]),
    ]
        sites=[siteind("GenericSpin"; two_s=round(Int,2s), conserve_sz=false) for s in spins]
        H=graph_heisenberg_hamiltonian(edges,sites)
        tensor=prod(H)
        d=prod(dim.(sites))
        matrix=reshape(Array(tensor, prime.(sites)..., sites...),d,d)
        @test matrix ≈ matrix' atol=1e-13
        expected=vec(readdlm(joinpath(root,name*".txt"),Float64))
        @test eigvals(Hermitian(matrix)) ≈ expected atol=1e-10 rtol=1e-10
        Random.seed!(20261021)
        psi=random_mps(sites;linkdims=2)
        energy,gs=dmrg(H,psi;nsweeps=8,maxdim=[4,8,16,32],cutoff=1e-12,outputlevel=0)
        @test energy ≈ minimum(expected) atol=1e-8 rtol=1e-8
        @test norm(gs) ≈ 1 atol=1e-10
    end
    @test_throws Exception parse_exchange_edges("1,2,1;2,1,2",3)
    @test_throws Exception parse_exchange_edges("1,1,1",3)
    @test_throws Exception parse_exchange_edges("1,4,1",3)
    @test_throws Exception parse_exchange_edges("1,2,NaN",3)
end
